transforms.code:

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['scheduleOperations']['enabled']:
		canCreate = True
		canEdit = True if value['eventInfo']['scheduleBlockId'] is not None else False

action = {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

return action

onChange.script:
if currentValue.value != 'Production':
	self.custom.values.wo = None
	self.custom.values.qty = None

if origin == 'Browser': 
	self.view.custom.values.assetPath = None if not self.props.value else system.kanoa.utilities.getFieldValue('assetPath', system.kanoa.asset.getAssets({'assetId':self.props.value}))

return

config.script:
if self.view.custom.userAction['canCreate'] or self.view.custom.userAction['canUpdate']:
	system.perspective.openPopup('color picker', 'kanoa/core/templates/colorPicker/main', params={'color': self.view.custom.values.color}, overlayDismiss=True)

return

